function stockRows(holdings=false){const positions={'600036':{qty:200,cost:8019.84},'600519':{qty:100,cost:128160},'600900':{qty:300,cost:8481.60},'601088':{qty:100,cost:4819.2}};return `<div>${stocks.filter(s=>!holdings||positions[s[1]]).map(([n,c,p,r])=>`<button class="menu-row" data-action="stock" data-code="${c}"><img class="stock-logo" src="assets/company-logos/${c}.${c==='601857'?'svg':'png'}" alt="${n}标志"><span class="grow">${n}<small>${c}${holdings?' '+positions[c].qty+'股':''}</small>${holdings?`<small>成本 ${money(positions[c].cost)}</small>`:''}</span><span style="text-align:right">${holdings?money(Number(p)*positions[c].qty):p}<small class="block ${r.startsWith('+')?'positive':''}">${holdings?'参考市值':r}</small></span></button>`).join('')}</div>`}

function me(){return `${header('我的','')}<div class="profile"><span class="avatar">林</span><div><h2>小林</h2></div></div><div class="card" style="padding-top:4px;padding-bottom:4px">${go('已连接账户','me/accounts','wallet')}${go('任务权限','me/permissions','shield')}${go('消息偏好','me/notifications','bell')}</div><div class="spacer"></div><div class="card" style="padding-top:4px;padding-bottom:4px">${go('模型与连接','me/model','spark')}${go('伙伴的工作方式','me/prompt','list')}${go('演示事件','me/events','calendar')}${go('关于 FinPilot','me/about','info')}</div><div class="spacer"></div><div class="card"><div class="row between"><div class="grow"><h3>暂停伙伴</h3><p class="muted" style="margin-top:6px">停止新行动，已提交操作仍会核实。</p></div><button class="toggle ${state.paused?'on':''}" role="switch" aria-checked="${state.paused}" aria-label="暂停伙伴" data-action="pause-bot"></button></div></div>`}
function subMe(id){let title={accounts:'已连接账户',permissions:'任务权限',notifications:'消息偏好',model:'模型与连接',prompt:'伙伴的工作方式',events:'演示事件',about:'关于 FinPilot'}[id]||'设置';let top=header(title,'',`<a class="icon-btn" href="#/me" aria-label="返回我的">${icon('back')}</a>`);if(id==='accounts')return top+`<div class="card"><div class="row"><span class="icon-box">${icon('wallet')}</span><div><h3>工资账户 0826</h3><small>权限随任务申请</small></div></div><div class="divider"></div><div class="row"><span class="icon-box">${icon('card')}</span><div><h3>生活账户 1608</h3><small>${state.cardLocked?'已暂停卡片消费':'使用中'}</small></div></div></div>`;if(id==='permissions')return top+(state.tasks.some(t=>t.granted)?state.tasks.filter(t=>t.granted).map(t=>`<div class="card"><h3>${t.title}</h3><p class="muted" style="margin:10px 0">${scenarios[t.key].permission}</p><small>仅限此任务 可随时撤销</small>${button('撤销权限','revoke','quiet full',`data-id="${t.id}"`)}</div>`).join(''):'<div class="empty">暂未授予任务权限。每项任务首次使用操作时，会先向你申请。</div>');if(id==='notifications')return top+`<div class="card"><div class="row between"><div><h3>重要事项及时提醒</h3><small>资金缺口、异常交易、待你确认</small></div><button class="toggle ${state.notifications?'on':''}" role="switch" aria-checked="${state.notifications}" aria-label="重要提醒" data-action="notifications"></button></div><div class="divider"></div><h3>普通变化，每晚汇总</h3><p class="muted" style="margin-top:8px">每天 20:00 安静时间 22:00—08:00</p><div class="divider"></div><div class="row between"><div><h3>减少动画</h3><small>关闭呼吸和过渡动效</small></div><button class="toggle ${state.reduceMotion?'on':''}" role="switch" aria-checked="${!!state.reduceMotion}" aria-label="减少动画" data-action="reduce-motion"></button></div></div>`;if(id==='model')return top+`<form id="model-form" class="form"><label>Base URL<input id="base-url" type="url" value="https://www.micuapi.ai/v1" autocomplete="off" required></label><label>API Key<input id="api-key" type="password" placeholder="仅本次服务会话保存" autocomplete="new-password" spellcheck="false"></label><label>模型<input id="model-name" value="deepseek-v4-flash-0731" readonly></label><p class="notice">密钥仅保留于本地服务内存，页面不会回显。重启服务后需重新输入。</p><p id="model-error" class="error-text" role="alert"></p><button class="primary full" type="submit">保存本次连接</button>${button('清除连接','clear-api','secondary full')}</form><div class="spacer"></div><div class="card"><h3>连接状态</h3><p class="muted" id="api-status" style="margin-top:8px">${apiStatus.configured?'密钥已配置于服务端内存':apiStatus.enabled?'尚未配置密钥':'本地场景可用；外部连接尚未启用'}</p><p class="muted" id="model-usage" aria-live="polite">${esc(modelUsageText())}</p></div>`;if(id==='prompt')return top+`<div class="form"><label>本轮系统提示词<textarea id="system-prompt" readonly aria-readonly="true">${esc(prompt)}</textarea></label><small>与当前服务实际使用的身份和场景合同一致。权限、核对与执行规则独立生效。</small></div>`;if(id==='events')return top+`<div class="stack">${Object.entries(scenarios).filter(([k])=>!['transfer','risk_transfer'].includes(k)).map(([k,s])=>button(`<span class="grow" style="text-align:left">${s.eyebrow}<small class="block">${s.title}</small></span>${icon('arrow')}`,'event','card row',`data-key="${k}"`)).join('')}</div><div class="spacer"></div>${button('查看一周总结','weekly','secondary full')}${button('重置这一周','reset','quiet full')}`;return top+`<div class="center">${companion()}<h2>FinPilot</h2></div><div class="spacer"></div><div class="card"><p>本地交互演示版，交易、银行账户、订阅和消息事件使用可控本地状态，不接真实银行，不会进行真实转账或购买。</p><div class="divider"></div><p class="muted">模型仅参与对话，不拥有资金工具权限。外部 API 连接需单独配置；未配置时不调用模型，不以固定回答替代。</p><div class="divider"></div><small>FinPilot 是独立项目，非 OpenAI 产品。设计借鉴持续委托与主动跟进的交互理念。v0.1 本地版本</small></div>`}
async function showResearch(code,span=60,index=null){const stock=stocks.find(x=>x[1]===code);if(!stock)return;const request=++researchEpoch;showModal(stock[0],'<p class="muted">正在读取历史资料…</p>');const epoch=modalEpoch;try{const html=await researchDetail(code,stock,span,index);if(modal&&request===researchEpoch&&epoch===modalEpoch)showModal(stock[0],html);}catch{if(modal&&request===researchEpoch&&epoch===modalEpoch)showModal(stock[0],'<p class="error-text">历史资料暂不可用，请稍后重试。</p>');}}
function resizeComposer(){const el=document.querySelector('#chat-input');if(!el)return;el.style.height='auto';el.style.height=Math.min(120,Math.max(44,el.scrollHeight))+'px';el.style.overflowY=el.scrollHeight>120?'auto':'hidden'}
function render(){botScroll.beforeRender();ensureFinance(state);page=(location.hash.replace(/^#\/?/,'')||'today');let view;if(page==='today')view=today();else if(page==='bot')view=bot();else if(page==='bot/tasks')view=tasks();else if(page.startsWith('bot/task/'))view=taskPage(page.split('/')[2]);else if(page.startsWith('operation/'))view=operationPage(page.split('/')[1]);else if(page==='finance'||page.startsWith('finance/'))view=finance();else if(page==='investment')view=invest();else if(page==='me')view=me();else if(page.startsWith('me/'))view=subMe(page.split('/')[1]);else view=today();document.documentElement.dataset.motion=state.reduceMotion?'reduce':'normal';app.className='app-shell';app.innerHTML=`<main class="page">${storageError?`<p class="notice" role="alert">${esc(storageError)}</p>`:''}${view}</main>${nav()}`;document.documentElement.classList.toggle('hidden-page',document.hidden);document.documentElement.dataset.reduceMotion=String(!!state.reduceMotion);const nativePage=['finance','investment'].includes(page)||page.startsWith('finance/');app.dataset.approvedUi=nativePage?baseline.role():'home';app.dataset.route=page.startsWith('finance/')?page.split('/')[1].split('?')[0]:page==='finance'?(financial==='ledger'?'ledger':financial==='charts'?'visualization':'home'):page==='investment'?(investment==='research'?'research':investment==='wealth'?'holdings':'investment'):page==='bot'?'assistant':page==='today'?'home':'settings';document.body.dataset.approvedUi=app.dataset.approvedUi;app.toggleAttribute('data-dot-page',!nativePage);app.classList.toggle('dot-ui',!nativePage);overlay.classList.add('dot-ui');if(!nativePage){app.querySelectorAll('.card').forEach(e=>e.classList.add('ap-home-card'));app.querySelectorAll('.primary').forEach(e=>e.classList.add('ap-w-button','ap-w-primary'));app.querySelectorAll('.secondary').forEach(e=>e.classList.add('ap-w-button'))}baseline.mount();resizeComposer();state.messages.forEach((m,i)=>seenMessageKeys.add(m.id||(i+':'+m.role)));state.tasks.forEach(t=>seenTaskIds.add(t.id));if(page==='bot'&&busy)paintedStreamId=streamEntranceId;botScroll.afterRender(page==='bot');}
function closeModal({history:move=true,consume=false}={}){modalEpoch++;researchEpoch++;overlay.innerHTML='';modal=null;lastFocus?.focus?.();if(move)navigation?.dismissOverlay({consume});}
function showModal(title,body,{history:move=true}={}){if(move)navigation?.openOverlay({title,body});modalEpoch++;if(!modal)lastFocus=document.activeElement;modal=true;overlay.innerHTML=`<div class="sheet-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="handle"></div><div class="row between"><h2>${title}</h2>${button(icon('close'),'close','sheet-close','aria-label="关闭"')}</div>${body}</section></div>`;overlay.querySelector('button,input,select,textarea')?.focus();}
function task(id){return state.tasks.find(t=>t.id===id)}
function start(key){const origin=navigation.snapshot();invalidateAgentRequest();leaveWorkspace(state);validationHistory.length=0;const t=createTask(state,key,{reuse:false});t.uiOrigin=origin;if(key==='investment')t.title='申购灵活现金';if(key==='redemption')t.title='赎回灵活现金';if(origin.route==='#/bot'){t.agentOrigin=true;selectTask(state,t.id,currentAgentRun);save();render();}else{save();navigation.go('#/operation/'+t.id,{kind:'operation',taskId:t.id,returnTo:origin});}}
function step(id,action,payload={}){const t=transition(state,id,action,payload);applyConsequences(state,t);save();render();}
function runLocal(t){try{const next=structuredClone(state),result=executeLocalTask(next,t.id),done=next.tasks.find(x=>x.id===t.id);if(done?.status==='done'&&done.agentOrigin&&!next.messages.some(m=>m.taskReceipt===done.receipt)){next.messages.push({id:crypto.randomUUID(),role:'assistant',text:doneText(done),taskReceipt:done.receipt,card:{type:'task_receipt',data:{title:done.title,target:done.target,amount:done.amount,receipt:done.receipt}}});next.agentWorkspaceVisible=false;}save(next);state=next;render();if(done?.status==='done'&&(page.startsWith('operation/')||page.startsWith('bot/task/'))){navigation.back(operationOrigin(done),()=>showModal('操作完成',`<div class="operation-result center"><h3>${esc(done.title)}</h3><strong class="amount money">${money(done.amount)}</strong><p>已完成</p><small class="receipt">${esc(done.receipt)}</small></div>`));}else toast(result.status==='completed'?'处理完成，回执与流水已保存。':'执行条件已变化，请核对安排。');}catch(error){render();toast(error.message)}}
function recover(){state.tasks.forEach(t=>{if(t.status==='executing'){t.status='unknown';t.logs.push({text:'页面恢复，先核实已提交操作，不重新发起',at:Date.now()})}});save()}
function updateStream(){const el=document.querySelector('#stream-output');if(el)el.textContent=streamText;}
let lastUser='',lastOriginId='';const requests=requestGate();
function invalidateAgentRequest(){requests.cancel();aborter=null;busy=false;streamText='';streamError='';}
// This array starts empty on this page load. It is NOT hydrated from state,
// localStorage, old conversations, settings preferences or financial data.
const currentAgentRun=crypto.randomUUID(),validationHistory=[];
async function send(text,options={}){
 if(busy||typeof text!=='string'||!text.trim())return;
 botScroll.forceBottom();
 lastUser=text;streamError='';streamText='';const originId=options.originTurnId||crypto.randomUUID();lastOriginId=originId;
 if(!state.messages.some(m=>m.id===originId))state.messages.push({id:originId,role:'user',text:text.slice(0,2000)});
 state.agentWorkspaceVisible=!!options.clarification;save();busy=true;streamEntranceId++;const ticket=requests.begin(),controller=ticket.controller;aborter=controller;render();
 try{
  const connection=await apiInit({paint:false});
  if(!requests.valid(ticket))throw new DOMException('Aborted','AbortError');
  if(!connection.configured||!connection.enabled)throw Error('尚未连接真实模型。请到“我的 → 模型与连接”填写本次连接；这条消息未调用模型。');
  const focus=state.tasks.find(t=>t.id===state.agentFocus&&t.agentRunId===currentAgentRun&&!['done','cancelled','blocked'].includes(t.status));
  const active=focus?{id:focus.id,kind:focus.kind,fields:{amount_minor:Math.round(focus.amount*100),payee_id:focus.payeeId||null,source_account:focus.sourceAccount||null,currency:focus.currency||'CNY',scheduled_date:focus.scheduledDate||null,purpose:focus.purpose||null,subscription_id:focus.subscriptionId||null,subscription_action:focus.subscriptionAction||null,transaction_ref:focus.transactionRef||null}}:null;
  const draft=state.agentDraft?.agentRunId===currentAgentRun?{id:state.agentDraft.id,fields:state.agentDraft.fields,missing:state.agentDraft.missing,choice_order:['family','travel','cash']}:null;
  await refreshAgentContract();
  if(!requests.valid(ticket))throw new DOMException('Aborted','AbortError');
  const request={validation_scope:'finpilot-fifteen-v1',text,tool_catalog:QUESTION_CATALOG.filter(q=>availableQueries.has(q.id)).map(q=>q.id),run_history:validationHistory.slice(-8),run_draft:draft,run_active_task:active,clarification:options.clarification||null};
  // No state.messages, preferences, tool facts, ledger or positions in request.
  const res=await fetch('/api/agent',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(request),signal:controller.signal});
  const data=await res.json();if(!res.ok)throw Error(data.message||'模型连接暂不可用，未创建新任务。');
  if(!requests.valid(ticket))throw new DOMException('Aborted','AbortError');
  if(data.source!=='llm'||!data.provider?.completed)throw Error('没有取得完整、可验证的模型结果。');
  // Deterministic finance tools run LOCALLY after semantic tool selection.
  let positions=null;if(data.result.query==='holdings'){try{positions=await baseline.request('/positions');}catch{}}
  if(controller.signal.aborted)throw new DOMException('Aborted','AbortError');
  const facts=buildAgentFacts(state,positions,data.result.period_month||'2026-11'),output=applyAgentResult(state,data.result,facts,{originTurnId:originId,userText:text,agentRunId:currentAgentRun});
  validationHistory.push({role:'user',text:text.slice(0,1200)},{role:'assistant',text:data.result.reply.slice(0,1200)});
  state.messages.push({id:crypto.randomUUID(),role:'assistant',text:output.text,card:output.card,taskId:output.taskId,source:'llm',snapshotId:facts.snapshot_id,model:data.provider.returned_model||data.provider.requested_model,usage:data.provider.usage});save();
 }catch(error){
  if(!requests.owns(ticket))return;
  if(error.name==='AbortError')state.messages.push({id:crypto.randomUUID(),role:'assistant',text:'已停止生成，未创建新任务。',source:'status'});
  else streamError=error.message;
  save();
 }finally{if(requests.owns(ticket)){requests.finish(ticket);busy=false;streamText='';aborter=null;refreshModelUsage();refreshAgentContract();render();}}
}

let modelUsage=null;
function modelUsageText(){if(!modelUsage)return '用量暂不可用';const count=modelUsage.budget?.agent_requests,tokens=modelUsage.last_request?.usage?.total_tokens;return (Number.isSafeInteger(count)?`累计请求 ${count.toLocaleString('zh-CN')} 次`:'用量暂不可用')+(Number.isSafeInteger(tokens)?`，最近一次 ${tokens.toLocaleString('zh-CN')} tokens`:'');}
async function refreshModelUsage(){try{const r=await fetch('/api/health',{signal:AbortSignal.timeout(1500)});if(!r.ok)return;const d=await r.json();modelUsage={budget:{agent_requests:d.budget?.agent_requests},last_request:{usage:{total_tokens:d.last_request?.usage?.total_tokens}}};const el=document.querySelector('#model-usage');if(el)el.textContent=modelUsageText();}catch{}}
let sessionPromise=null;async function apiInit({paint=true}={}){try{if(!sessionPromise)sessionPromise=fetch('/api/session').then(async r=>{if(!r.ok)throw Error('本地会话不可用');return r.json();}).finally(()=>{sessionPromise=null});const d=await sessionPromise;csrf=d.csrf;apiStatus=d;refreshModelUsage();if(paint)render();return d;}catch(error){if(paint)toast('本地服务暂不可用。请保留页面，稍后重试。');throw error;}}
const baseline=createBaselineBridge({getState:()=>state,save,render,esc,money,showModal,closeModal,start,navigateInvestment:v=>navigation.go('#/investment',{investment:v}),navigateFinancial:v=>navigation.go('#/finance',{financial:v}),navigateCapture:route=>navigation.go('#'+route,{kind:'detail',returnTo:navigation.snapshot()}),registerRiskNavigation:()=>navigation.openOverlay({kind:'risk'}),closeRiskNavigation:()=>navigation.dismissOverlay(),icon,getCsrf:()=>csrf,refreshSession:()=>apiInit({paint:false}),namespace:KEY,persistState:next=>{save(next);state=next;},setFinancial:v=>financial=v,setInvestment:v=>investment=v});
