function rememberClarification(e){const form=e.target.closest?.('#agent-clarification-form');if(!form||state.agentDraft?.id!==form.dataset.draft)return;const draft=continueDraft(state,form.dataset.draft,currentAgentRun);state.agentDraft=draftWithInputs(draft,Object.fromEntries(new FormData(form)));rememberDraft(state);save();}
app.addEventListener('input',rememberClarification);app.addEventListener('change',rememberClarification);

app.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='agent-clarification-form'){try{if(state.agentDraft?.id!==e.target.dataset.draft)throw Error('这次补充已结束，请使用当前表单。');continueDraft(state,e.target.dataset.draft,currentAgentRun);const fields=readClarification(e.target);state.agentDraft=draftWithInputs(state.agentDraft,Object.fromEntries(new FormData(e.target)));rememberDraft(state);save();await send('补充安排：'+clarificationText(fields),{clarification:fields});}catch(error){const box=e.target.querySelector('[role=alert]');if(box)box.textContent=error.message;else toast(error.message)}return;}try{if(await baseline.submit(e))return;}catch(error){toast(error.message);const feedback=e.target.querySelector('[role=alert]');if(feedback)feedback.textContent=error.message;return;}if(e.target.id==='chat-form'){const text=document.querySelector('#chat-input')?.value;await send(text||'');}else if(e.target.id==='model-form'){let field=document.querySelector('#api-key');const key=field.value;field.value='';try{const r=await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({mode:'api',base_url:document.querySelector('#base-url').value,key})});const d=await r.json();if(!r.ok)throw Error(d.message);apiStatus=d;toast('本次连接已更新。');render();}catch(e){document.querySelector('#model-error').textContent=e.message;}}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,t=task(id);try{navigation.remember();if(a==='operation-back'){e.preventDefault();invalidateAgentRequest();editingTask=null;navigation.back(operationOrigin(t));return;}if(a==='operation-edit-cancel'){editingTask=null;render();return;}if(a==='operation-confirm'){const next=structuredClone(state);const approved=authorizeOperation(next,id,{revision:Number(b.dataset.revision),parameters:decodeURIComponent(b.dataset.parameters||'')});save(next);state=next;render();if(approved.status==='executing')runLocal(approved);return;}if(a==='investment-section'){navigation.go('#/investment',{investment:b.dataset.value==='research'?'research':b.dataset.value==='holdings'?'wealth':'holdings'});return;}if(a==='resume-agent-draft'){invalidateAgentRequest();continueDraft(state,b.dataset.draft,currentAgentRun);validationHistory.length=0;save();location.hash='/bot';render();return;}if(a==='open-agent-task'){e.preventDefault();const origin=navigation.snapshot();invalidateAgentRequest();validationHistory.length=0;if(t?.agentOrigin&&!['done','cancelled','blocked'].includes(t.status)){selectTask(state,id,currentAgentRun);save();navigation.go('#/bot');}else navigation.go('#/operation/'+id,{kind:'operation',taskId:id,returnTo:origin});return;}if(a==='cancel-agent-draft'){if(state.agentDraft?.id===b.dataset.draft){invalidateAgentRequest();leaveWorkspace(state,{cancel:true});validationHistory.length=0;save();render();}return;}if(a==='agent-month'||a==='agent-ledger'){const month=b.dataset.month;if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))throw Error('月份无效');baseline.ui.month=month;baseline.ui.ledgerRange=null;baseline.ui.filter={q:'',category:b.dataset.query==='dining_month'?'餐饮':'',type:b.dataset.query==='income_month'?'income':'',minMinor:b.dataset.query==='large_expenses'?100000:0};financial='ledger';location.hash='/finance';render();return;}if(await baseline.action(a,b))return;if(a==='capture-back'){e.preventDefault();navigation.back({route:'#/finance',financial:'ledger',investment});return}if(a==='close-link'){e.preventDefault();const origin=navigation.snapshot();const destination=b.getAttribute('href');closeModal({consume:true});if(destination)navigation.go(destination,{kind:'operation',returnTo:origin});return}if(a==='close'){closeModal();return}if(a==='scenario'){closeModal({consume:true});start(b.dataset.key);return}if(a==='recognized'){state.events=state.events.filter(k=>k!=='safety');save();render();toast('已确认本人消费，本次警报已结束。');return}if(a==='chat-scenario'){location.hash='/bot';await send(b.dataset.text||b.textContent.trim());return}if(a==='new-task'){botScroll.forceBottom();invalidateAgentRequest();leaveWorkspace(state);validationHistory.length=0;save();location.hash='/bot';render();document.querySelector('#chat-input')?.focus();return}if(a==='stop'){aborter?.abort();return}if(a==='retry'){await send(lastUser,{originTurnId:lastOriginId});return}if(a==='receipt-ledger'){filter=b.dataset.receipt;baseline.receipt(filter);financial='ledger';location.hash='/finance';render();return}if(a==='financial'){let tab=b.dataset.tab;if(tab==='budget'){tab='charts';baseline.ui.productAnalysisTab='budget'}navigation.go('#/finance',{financial:tab});return}if(a==='investment'){navigation.go('#/investment',{investment:b.dataset.tab});return}if(a==='mask'){state.mask=!state.mask;save();render();return}if(a==='trend-point'){trend=Number(b.dataset.index);render();return}if(a==='category-detail'){filter=b.dataset.category;financial='ledger';render();return}if(a==='day-detail'){filter='11月'+b.dataset.day+'日';financial='ledger';render();return}if(a==='category'){category=Number(b.dataset.index);render();return}if(a==='pause-bot'){state.paused=!state.paused;save();render();return}if(a==='reduce-motion'){state.reduceMotion=!state.reduceMotion;save();render();return}if(a==='notifications'){state.notifications=!state.notifications;save();render();return}if(a==='permission'){showModal('这件事，需要你的授权',`<p class="muted">仅用于「${esc(t.title)}」</p><div class="permission-list"><span>${icon('check')}${esc(taskPermission(t)||scenarios[t.key].permission)}</span><span>${icon('check')}仅限所选账户与本任务</span><span>${icon('check')}任务结束失效，可随时撤销</span></div><p class="notice">授权后仍会展示具体操作；涉及资金与卡片保护时，另行确认或验证。</p><div class="task-actions">${button('允许本任务使用','grant','primary',`data-id="${id}"`)}${button('暂不授权','close','secondary')}</div>`);return}if(a==='grant'){step(id,'grant');closeModal();return}if(a==='review'){showModal('核对这次安排',`${taskReviewHTML(t,{state,esc})}<p>${t.kind==='subscription'?(t.subscriptionAction==='keep'?'下次续费保持开启，本期权益不变。':t.subscriptionAction==='downgrade'?'仅调整下次套餐，本期权益不变。':'仅取消下次续费，保留本期权益。'):t.kind==='card'?'临时锁定卡片并提交交易核查，不关闭账户。':t.kind==='planning'?'增加旅行预算，房租和生活费不变，下月提醒补存。':t.kind==='refund'?'核实原退款状态，不重复发起退款。':'房租和生活费预算预留保持不变。'}</p><div class="notice">方案 v${t.revision} 修改参数后需要重新确认。</div>${button('确认这次操作','confirm','primary full',`data-id="${id}" data-revision="${t.revision}" data-parameters="${encodeURIComponent(parameterFingerprint(t))}"`)}`);return}if(a==='confirm'){step(id,'confirm',{revision:Number(b.dataset.revision),parameters:decodeURIComponent(b.dataset.parameters||'')});closeModal();if(t.status==='executing')runLocal(t);return}if(a==='verify'){showModal('确认是你本人',`<div class="verification">${icon('shield')}<h3 style="margin:16px 0 8px">保护这次重要操作</h3><p class="muted">${esc(t.target)}${t.amount?' '+money(t.amount):''}</p></div>${button('验证身份并继续','verified','primary full',`data-id="${id}"`)}<p class="notice center">验证仅适用于当前参数与本次操作。</p>`);return}if(a==='verified'){step(id,'verify',{verified:true});closeModal();runLocal(t);return}if(a==='edit'&&(page==='bot'||page.startsWith('operation/')||page.startsWith('bot/task/'))){editingTask=id;render();document.querySelector('#inline-task-edit input')?.focus();return;}if(a==='edit'){showModal('修改安排',`<form id="edit-form" data-id="${id}" class="form">${taskEditHTML(t,{esc})}<p class="notice">保存后，之前的操作确认会失效。</p><button class="primary full">保存新安排</button></form>`);return}if(['cancel','pause','resume','revoke'].includes(a)){step(id,a);closeModal();if(a==='cancel'&&(page.startsWith('operation/')||page.startsWith('bot/task/')))navigation.back(operationOrigin(t));toast(a==='revoke'?'权限已撤销。':'任务已更新。');return}if(a==='reconcile'){if(t.status!=='unknown')throw Error('没有待核实结果');const result=reconcileLocalTask(state,id);save();render();toast(result.status==='completed'?'已查到相同回执，没有重复执行。':result.status==='pending'?'本地执行仍在处理中，未重复发起。':result.status==='failed'?'执行记录为失败，未记入资金流水。':'没有找到可核实记录，已保持暂停，不会自动重发。');return}if(a==='compare'){showModal('先看用钱时间',`<div class="plan-row"><strong>灵活现金 R1</strong><span>近期资金</span></div><div class="plan-row"><strong>长期均衡 R3</strong><span>一年以上</span></div><p class="notice">近期房租与生活费不应投入长期产品。产品均有风险，收益不保证。</p>${button('和伙伴安排','scenario','primary full','data-key="investment"')}`);return}if(a==='research-span'){await showResearch(b.dataset.code,Number(b.dataset.span));return}if(a==='stock'){await showResearch(b.dataset.code);return}if(a==='old-stock-disabled'){let s=stocks.find(x=>x[1]===b.dataset.code);showModal(s[0],`<span class="label">${s[1]} 2026-10-23 收盘参考</span><div class="big money" style="margin:18px 0">${s[2]}</div><p class="muted">这里保留历史参考信息，帮助你理解持仓。可以让伙伴结合用钱计划解释资产安排。</p>${button('和伙伴聊聊','stock-chat','primary full')}`);return}if(a==='stock-chat'){closeModal();location.hash='/bot';await send('帮我看看持仓和近期用钱安排');return}if(a==='bill'){showModal(b.dataset.name,`<div class="big money" style="margin:18px 0">${esc(b.dataset.amount)}</div><div class="plan-row"><span>日期</span><span>${esc(b.dataset.date)}</span></div><div class="plan-row"><span>分类</span><span>${esc(b.dataset.category)}</span></div><small>账户 生活账户 1608${b.dataset.movement==='principal'?' 本金划转，不计消费':''}</small>${b.dataset.receipt?`<div class="divider"></div><p class="receipt">对应回执 ${esc(b.dataset.receipt)}</p><a class="secondary full" href="#/bot/task/${esc(b.dataset.task)}" data-action="close-link">查看原任务</a>`:''}`);return}if(a==='event'){const k=b.dataset.key;if(!state.events.includes(k))state.events.push(k);save();location.hash='/today';toast('新事件已到达。');return}if(a==='weekly'){showModal('这一周，安排得怎么样',`<p>已完成 ${state.tasks.filter(t=>t.status==='done').length} 项任务，仍有 ${state.tasks.filter(t=>!['done','cancelled','blocked'].includes(t.status)).length} 项在跟进。</p><div class="divider"></div><p class="muted">房租与生活费预算保持不变。你可以随时调整委托。</p>${button('查看我的任务','tasks','primary full')}`);return}if(a==='tasks'){closeModal();location.hash='/bot/tasks';return}if(a==='reset'){showModal('重新开始这一周？',`<p class="muted">会清除本地任务和对话，恢复初始演示数据。API 密钥不会被写入或导出。</p><div class="spacer"></div>${button('重新开始','reset-confirm','primary full')}`);return}if(a==='reset-confirm'){invalidateAgentRequest();validationHistory.length=0;state=fresh();save();closeModal();location.hash='/today';render();return}if(a==='clear-api'){const r=await fetch('/api/config',{method:'DELETE',headers:{'X-CSRF-Token':csrf}});if(!r.ok)throw Error('清除失败，请重试');apiStatus.configured=false;render();toast('连接已清除。');return}}catch(error){toast(error.message)}});
overlay.addEventListener('change',async e=>{if(e.target.id==='research-point'){const box=document.querySelector('#research-detail');const epoch=modalEpoch,request=++researchEpoch;const html=await researchDetail(box.dataset.code,stocks.find(x=>x[1]===box.dataset.code),Number(box.dataset.span),Number(e.target.value));if(box.isConnected&&epoch===modalEpoch&&request===researchEpoch)box.outerHTML=html;}});
overlay.addEventListener('submit',e=>{e.preventDefault();try{if(e.target.id==='edit-form'){step(e.target.dataset.id,'edit',readTaskEdit(e.target));closeModal();}}catch(e){toast(e.message)}});
app.addEventListener('input',e=>{if(e.target.id==='chat-input')resizeComposer();if(baseline.input(e))return;if(e.target.id==='bill-search'){filter=e.target.value;document.querySelector('#ledger-results').innerHTML=ledger()}if(e.target.id==='trend'){trend=Number(e.target.value);const pos=window.scrollY;render();document.querySelector('#trend')?.focus({preventScroll:true});window.scrollTo(0,pos);}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('svg [role=button][data-action]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));return;}if(e.key==='Escape'&&modal)closeModal();if(e.key==='Tab'&&modal){const xs=[...overlay.querySelectorAll('button,input,textarea,select,a')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===xs[0]){e.preventDefault();xs.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===xs.at(-1)){e.preventDefault();xs[0]?.focus()}}if(e.key==='Enter'&&!e.shiftKey&&e.target.id==='chat-input'){e.preventDefault();send(e.target.value)}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const incoming=JSON.parse(e.newValue);if(incoming.version===1){if(incoming.agentGeneration!==state.agentGeneration)invalidateAgentRequest();state=incoming;render();}}catch{}}});
document.addEventListener('visibilitychange',()=>document.documentElement.classList.toggle('hidden-page',document.hidden));
navigation=createViewNavigation({win:window,read:()=>({financial,investment}),apply:v=>{if(page.startsWith('operation/')&&v.route!=='#/'+page){const leaving=task(page.split('/')[1]);if(leaving&&['permission','review','verify','paused'].includes(leaving.status)){transition(state,leaving.id,'cancel');save();}}financial=v.financial||'overview';investment=v.investment||'holdings';editingTask=null;if(busy&&v.route!=='#/bot')invalidateAgentRequest();},render,clearOverlay:()=>{closeModal({history:false});baseline.disposeRisk();},restoreOverlay:c=>c.kind==='risk'?baseline.openRisk({history:false}):showModal(c.title,c.body,{history:false})});
